std::vector<uint32_t> observed(width*width),target(width*width);for(int g=0;g<p;++g)for(int r:rows[g])observed[r]^=baseline[g];for(int i=0;i<n;++i)for(int j=0;j<n;++j)for(int k=0;k<n;++k){std::array<int,3> xyz{i*n+j,j*n+k,k*n+i};target[xyz[perm[0]]*width+xyz[perm[1]]]^=uint32_t(1)<<xyz[perm[2]];}if(observed!=target)throw std::runtime_error("original PW=Y failed");
std::vector<std::vector<int>> supports(c),active_supports(c),incidence(p);std::vector<int> delta(c),active(c);std::set<std::vector<int>> support_set;
for(int i=0;i<c;++i){int kind,size;if(!(in>>kind>>size)||kind<0||kind>2||size<3||size>128||(kind==0&&size!=3)||(kind==1&&size!=4))throw std::runtime_error("invalid circuit");Column total{};std::unordered_set<int> distinct;std::map<uint32_t,int> frequencies;int zeros=0,maximum=0;for(int j=0;j<size;++j){int g;if(!(in>>g)||g<0||g>=p||!distinct.insert(g).second)throw std::runtime_error("invalid circuit group");supports[i].push_back(g);incidence[g].push_back(i);maximum=std::max(maximum,++frequencies[baseline[g]]);zeros+=baseline[g]==0;if(baseline[g])active_supports[i].push_back(g);for(int bit=0;bit<10;++bit)total[bit]^=columns[g][bit];}if(std::any_of(total.begin(),total.end(),[](U x){return x;}))throw std::runtime_error("nonkernel circuit");std::sort(supports[i].begin(),supports[i].end());if(!support_set.insert(supports[i]).second)throw std::runtime_error("duplicate circuit");active[i]=active_supports[i].size();delta[i]=zeros-maximum;}
std::string extra;if(in>>extra)throw std::runtime_error("trailing kernel input");
std::ifstream excluded_input(o.exclude);U excluded_count;if(!(excluded_input>>magic>>excluded_count)||magic!="MMKQUARTETS1"||excluded_count>2000000)throw std::runtime_error("invalid exclusions");std::unordered_set<U> excluded;for(U i=0;i<excluded_count;++i){Row row;if(!(excluded_input>>row[0]>>row[1]>>row[2]>>row[3])||row[0]<0||row[0]>=row[1]||row[1]>=row[2]||row[2]>=row[3]||row[3]>=c||!excluded.insert(key(row)).second)throw std::runtime_error("invalid excluded quartet");}if(excluded_input>>extra)throw std::runtime_error("trailing exclusions");
std::map<uint32_t,int> labels{{0,0}};std::vector<int> label(p);for(int g=0;g<p;++g){auto it=labels.find(baseline[g]);if(it==labels.end())it=labels.emplace(baseline[g],labels.size()).first;label[g]=it->second;}if(labels.size()>94)throw std::runtime_error("rank93 distinct-label bound failed");
std::vector<int> promising(c),shorts;std::iota(promising.begin(),promising.end(),0);std::sort(promising.begin(),promising.end(),[&](int a,int b){return std::make_tuple(delta[a],-active[a],supports[a].size(),a)<std::make_tuple(delta[b],-active[b],supports[b].size(),b);});for(int i:promising)if(supports[i].size()<=8&&active[i])shorts.push_back(i);if(promising.size()>512)promising.resize(512);if(shorts.size()>512)shorts.resize(512);if(shorts.empty())shorts=promising;
