auto neighbor=[&](int i,const Row&chosen,int used){for(int attempt=0;attempt<32;++attempt){const auto&groups=(!active_supports[i].empty()&&(rng()&3)!=0)?active_supports[i]:supports[i];int j=pick(incidence[pick(groups)]);bool valid=true;for(int k=0;k<used;++k)valid&=chosen[k]!=j;if(valid)return j;}return -1;};
auto overlap=[&](int a,int b){size_t x=0,y=0;while(x<supports[a].size()&&y<supports[b].size()){if(supports[a][x]==supports[b][y])return true;if(supports[a][x]<supports[b][y])++x;else ++y;}return false;};
std::vector<Candidate> pool;pool.reserve(o.count*o.factor);std::unordered_set<U> seen;seen.reserve(o.count*o.factor*2);std::vector<unsigned char> membership(p);std::vector<int> touched;touched.reserve(512);auto bases=quartet::make_bases();
U attempts=0,excluded_hits=0,duplicates=0,bound_negative=0,work_rejected=0,invalid_proposal=0;std::array<U,3> proposed{},accepted{};auto start=std::chrono::steady_clock::now();auto elapsed=[&](){return std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count();};std::signal(SIGTERM,stop_handler);std::signal(SIGINT,stop_handler);
while(pool.size()<o.count*o.factor&&attempts<o.max_attempts&&!stopped){if((attempts&1023)==0&&elapsed()>=o.seconds)break;U attempt=attempts++;int mode=attempt%3;++proposed[mode];Row row{{-1,-1,-1,-1}};switch((attempt/3)%4){case 0:row[0]=rng()%5;break;case 1:row[0]=pick(promising);break;case 2:row[0]=pick(shorts);break;default:row[0]=rng()%c;}
row[1]=neighbor(row[0],row,1);if(row[1]<0){++invalid_proposal;continue;}row[2]=neighbor(mode==0?row[0]:row[1],row,2);if(row[2]<0){++invalid_proposal;continue;}row[3]=neighbor(mode==0?row[0]:row[2],row,3);if(mode==2){for(int tries=0;row[3]>=0&&!overlap(row[3],row[0])&&tries<15;++tries)row[3]=neighbor(row[2],row,3);if(row[3]>=0&&!overlap(row[3],row[0]))row[3]=-1;}if(row[3]<0){++invalid_proposal;continue;}std::sort(row.begin(),row.end());U identity=key(row);if(excluded.count(identity)){++excluded_hits;continue;}if(seen.count(identity)){++duplicates;continue;}
for(int bit=0;bit<4;++bit){for(int g:supports[row[bit]]){if(!membership[g])touched.push_back(g);membership[g]|=1<<bit;}}
std::array<std::array<unsigned char,94>,16> frequency{};std::array<int,16> distinct{},maximum{};int zeros=0,upper=0;unsigned present=0;for(int g:touched){int s=membership[g];int value=++frequency[s][label[g]];if(value==1)++distinct[s];maximum[s]=std::max(maximum[s],value);zeros+=label[g]==0;present|=1U<<(s-1);membership[g]=0;}touched.clear();for(int s=1;s<16;++s)upper+=maximum[s];if(upper<=zeros){++bound_negative;continue;}
int rank=quartet::present_rank(present);U work=0;for(const auto&basis:bases[rank])if((basis.present&present)==basis.present){U count=1;for(int k=0;k<basis.size;++k)count*=distinct[basis.classes[k]];work+=count;}if(o.max_work&&work>o.max_work){++work_rejected;continue;}seen.insert(identity);pool.push_back({row,work,rank,upper-zeros,int(std::count_if(row.begin(),row.end(),[](int i){return i<5;})),mode});++accepted[mode];}
std::sort(pool.begin(),pool.end(),[](const Candidate&a,const Candidate&b){return std::make_tuple(-a.new_count,-a.rank,a.work,a.row)<std::make_tuple(-b.new_count,-b.rank,b.work,b.row);});bool requested=pool.size()>=o.count;if(pool.size()>o.count)pool.resize(o.count);std::ostringstream catalog;catalog<<"MMKQUARTETS1 "<<pool.size()<<'\n';U work_sum=0;std::vector<U> work;std::array<U,5> ranks{},gains{};std::array<U,64> work_bins{};for(const auto&item:pool){catalog<<item.row[0]<<' '<<item.row[1]<<' '<<item.row[2]<<' '<<item.row[3]<<'\n';work_sum+=item.work;work.push_back(item.work);++ranks[item.rank];++gains[std::min(item.gain,4)];++work_bins[item.work?63-__builtin_clzll(item.work):0];}atomic_text(o.output+".quartets.txt",catalog.str());std::sort(work.begin(),work.end());auto quantile=[&](size_t numerator,size_t denominator){return work.empty()?U(0):work[std::min(work.size()-1,work.size()*numerator/denominator)];};
